window.AUTH=window.AUTH||{};window.AUTH["17-1657"]={"d":"17-1657","id":"2018/17-1657","n":"Mission Product Holdings, Inc. v. Tempnology, LLC","briefs":[{"k":"petitioner","label":"Brief of petitioner Mission Product Holdings, Inc.","date":"2018-12-10","url":"https://www.supremecourt.gov/DocketPDF/17/17-1657/74715/20181210195312218_17-1657%20ts.pdf","side":"pet","n":41},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2018-12-17","url":"https://www.supremecourt.gov/DocketPDF/17/17-1657/76566/20181217183017205_17-1657tsacUnitedStates.pdf","side":"us","n":44},{"k":"respondent","label":"Brief of respondent Tempnology, LLC, n/k/a Old Cold LLC","date":"2019-01-09","url":"https://www.supremecourt.gov/DocketPDF/17/17-1657/78978/20190109213804671_No.%2017-1657bs.pdf","side":"res","n":91},{"k":"reply","label":"Reply of petitioner Mission Product Holdings, Inc.","date":"2019-02-08","url":"https://www.supremecourt.gov/DocketPDF/17/17-1657/87659/20190208134723203_17-1657%20rb.pdf","side":"pet","n":17}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-1657_4f15.pdf","tr":true,"items":[{"t":"case","label":"2Die4Kourt v. Hillair Capital Management, LLC","cite":"2016 WL 4487895","y":2016,"court":"C.D. Cal. Aug. 23","by":{"0":"40"}},{"t":"case","label":"A&L Laboratories, Inc. v. Bou-Matic LLC","cite":"429 F.3d 775","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/429/775/","by":{"0":"38"}},{"t":"case","label":"American Express Co. v. Italian Colors Restaurant","cite":"570 U.S. 228","y":2013,"id":"2012/12-133","sc":1,"sum":"The Court held that a clause prohibiting class action suits was enforceable even though it would cause costly arbitration.","sumSrc":"Oyez","by":{"0":"56"}},{"t":"case","label":"ARP Films, Inc. v. Marvel Entertainment Group, Inc.","cite":"952 F.2d 643","y":1991,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/952/643/","by":{"0":"40"}},{"t":"case","label":"Associates Commercial Corp. v. Rash","cite":"520 U.S. 953","y":1997,"id":"1996/96-454","sc":1,"sum":"The Court held that section 506(a) of the Bankruptcy Code, which governs the value of a secured claim, directs the application of the replacement-value standard when debtor, in a repayment plan under Chapter 13, has exercised the cram-down provision.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Barcamerica International USA Trust v. Tyfield Importers, Inc.","cite":"289 F.3d 589","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/289/589/","by":{"0":"51, 54"}},{"t":"case","label":"BFP v. Resolution Trust Corp.","cite":"511 U.S. 531","y":1994,"id":"1993/92-1370","sc":1,"sum":"The Court ruled 5-4 that the value received for a property at a foreclosure sale can be reasonable even if it is different from the \"fair market value.\" A foreclosure sale alters market conditions and can lower a property's selling price.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Board of Trade of City of Chicago v. Johnson","cite":"264 U.S. 1","y":1924,"id":"scdb/1923-054","sc":1,"op":1,"sum":"1. Decisions of state courts defining property rights do not bind the federal courts in bankruptcy, when contrary to the policy and proper construction of the Bankruptcy Act.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"4, 24, 25, 29, 37","2":"46, 47","3":"5, 16, 18"}},{"t":"case","label":"Boscorale Operating, LLC v. Nautica Apparel, Inc.","cite":"749 N.Y.S.2d 233","y":2002,"court":"App. Div.","url":"https://www.courtlistener.com/c/N.Y.S.2d/749/233/","by":{"0":"40"}},{"t":"case","label":"Brown v. Marquette Savings & Loan Ass’n","cite":"686 F.2d 608","y":1982,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/686/608/","by":{"0":"47"}},{"t":"case","label":"Butner v. United States","cite":"440 U.S. 48","y":1979,"id":"1978/77-1410","sc":1,"sum":"Apart from certain special provisions, the Bankruptcy Act generally leaves the determination of property rights in the assets of a bankrupt's estate to BUTNER v. UNITED STATES","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20","3":"7"}},{"t":"case","label":"Central States, Southeast & Southwest Areas Pension Fund v. Basic American Industries, Inc.","cite":"252 F.3d 911","y":2001,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/252/911/","by":{"0":"18"}},{"t":"case","label":"Page(s) City of Oklahoma City v. Tuttle","cite":"471 U.S. 808","y":1985,"id":"1984/83-1919","sc":1,"sum":"The Court held that the district court’s instructions to the jury improperly allowed a plaintiff to impose liability on the city without proof of a single action taken by a municipal policy maker.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"55"}},{"t":"case","label":"College Savings Bank v. Florida Prepaid Postsecondary Education Expense Board","cite":"527 U.S. 666","y":1999,"id":"1998/98-149","sc":1,"sum":"The Court held that \"the federal courts are without jurisdiction to entertain this suit against an arm of the State of Florida.\" Justice Scalia concluded that \"the sovereign immunity of the State of Florida was neither validly abrogated by the Trademark Remedy Clarification Act, nor voluntarily waived by the State's activities in interstate commerce.\" Writing for the dissenting minority, Justice Stephen G. Breyer expressed the view that Congress possesses the authority to abrogate a state's sovereign immunity where necessary and proper to the exercise of a congressional power under the Constitution's Article I. Justice John Paul Stevens filed his own dissenting opinion and joined that of Justice Breyer.","sumSrc":"Oyez","by":{"0":"36","2":"54"}},{"t":"case","label":"Czyzewski v. Jevic Holding Corp.","cite":"137 S. Ct. 973","y":2017,"id":"2016/15-649","sc":1,"sum":"The Court determined that bankruptcy court cannot authorize a distribution of settlement proceeds in a manner that does not comply with the Bankruptcy Code’s priority distribution scheme.","sumSrc":"Oyez","by":{"0":"16, 27"}},{"t":"case","label":"Davis v. Blige","cite":"505 F.3d 90","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/505/90/","by":{"0":"43"}},{"t":"case","label":"Donnell v. Herring-Hall-Marvin Safe Co.","cite":"208 U.S. 267","y":1908,"id":"scdb/1907-071","sc":1,"sum":"A stockholder, even though also an officer, of a corporation bearing his family name does not necessarily lose his right'to carry on the business of manufacturing the same commodity under his own name because that corporation sold its good will, trade name, etc., and as a stockholder and officer he participated in the sale. He is not entitled, however, to use, and may be enjoined by the purchaser from using, any …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"Field v. Mans","cite":"516 U.S. 59","y":1995,"id":"1995/94-967","sc":1,"op":1,"sum":"After respondent Mans filed for relief under Chapter 11 of the Bankruptcy Code, petitioners William and Norinne Field alleged, in effect, that letters Mans had written to them constituted fraudulent representations on which they relied in continuing to extend credit to a corporation controlled by Mans, and that, accordingly, Mans's obligation to them as guarantor of the corporation's debt should be excepted from …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Page(s) K Mart Corp. v. Cartier, Inc.","cite":"485 U.S. 176","y":1988,"url":"https://supreme.justia.com/cases/federal/us/485/176/","sc":1,"by":{"0":"36, 37"}},{"t":"case","label":"Kentucky Fried Chicken Corp. v. Diversified Packaging Corp.","cite":"549 F.2d 368","y":1977,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/549/368/","by":{"0":"53"}},{"t":"case","label":"L.L. Brown Paper Co. v. Hydroiloid, Inc.","cite":"118 F.2d 674","y":1941,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/118/674/","by":{"0":"43"}},{"t":"case","label":"Leasing Service Corp. v. First Tennessee Bank National Ass’n","cite":"826 F.2d 434","y":1987,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/826/434/","by":{"0":"29"}},{"t":"case","label":"Lubrizol Enterprises v. Richmond Metal Finishers, Inc.","cite":"756 F.2d 1043","y":1985,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/756/1043/","op":5,"ar":8,"by":{"0":"13, 29, 30, 31, 33, 49","1":"6, 12, 28","2":"passim","3":"8"}},{"t":"case","label":"NLRB v. Bildisco & Bildisco","cite":"465 U.S. 513","y":1984,"id":"1983/82-818","sc":1,"op":2,"sum":"Noting the higher priority of post-petition claims.","sumSrc":"opinion","by":{"0":"17, 18, 55","1":"4, 5, 16, 20","2":"passim","3":"7, 13"}},{"t":"case","label":"O’Gilvie v. United States","cite":"519 U.S. 79","y":1996,"id":"1996/95-966","sc":1,"sum":"The Court held that the punitive damages received by the O'Gilvies were not received \"on account of\" personal injuries,\" and therefore the provision did not apply and the damages were taxable.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Ortho Pharmaceutical Corp. v. Genetics Institute, Inc.","cite":"52 F.3d 1026","y":1995,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/52/1026/","by":{"0":"43"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"0":"47","2":"39, 40, 50","3":"15"}},{"t":"case","label":"Raleigh v. Illinois Department of Revenue","cite":"530 U.S. 15","y":2000,"id":"1999/99-387","sc":1,"sum":"The Court held that \"[w]hen the substantive law creating a tax obligation puts the burden of proof on a taxpayer, the burden of proof on the tax claim in bankruptcy court remains where the substantive law put it (in this case, on the trustee in bankruptcy).\" The Court concluded that the bankruptcy estate's obligation to the Department was established by the state's tax code and that the Bankruptcy Code made no provision for altering the burden on a tax claim, and its silence said that no change was intended.","sumSrc":"Oyez","by":{"0":"20","2":"50"}},{"t":"case","label":"S&R Corp. v. Jiffy Lube International Inc.","cite":"968 F.2d 371","y":1992,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/968/371/","by":{"0":"40"}},{"t":"case","label":"Sanofi, S.A. v. Med-Tech Veterinarian Products, Inc.","cite":"565 F. Supp. 931","y":1983,"court":"D.N.J.","url":"https://www.courtlistener.com/c/F.%20Supp./565/931/","by":{"0":"44"}},{"t":"case","label":"Page(s) Sunbeam Products, Inc. v. Chicago American Manufacturing, LLC","cite":"686 F.3d 372","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/686/372/","op":4,"by":{"0":"passim","1":"9, 11, 14, 17, 31","2":"passim","3":"2"}},{"t":"case","label":"Thompkins v. Lil’ Joe Records, Inc.","cite":"476 F.3d 1294","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/476/1294/","by":{"0":"22, 26","1":"18"}},{"t":"case","label":"Travelers Casualty & Surety Co. of America v. Pacific Gas & Electric Co.","cite":"549 U.S. 443","y":2007,"id":"2006/05-1429","sc":1,"sum":"Justice Samuel Alito issued the unanimous opinion, which found that the Bankruptcy Code did not expressly waive the contractual obligation to reimburse attorney fees even if incurred in federal litigation.","sumSrc":"Oyez","by":{"0":"3, 20"}},{"t":"case","label":"United States v. Craft","cite":"535 U.S. 274","y":2002,"id":"2001/00-1831","sc":1,"op":1,"sum":"The Court held that each tenant possesses individual rights in the estate sufficient to constitute \"property\" or \"rights to property\" for the purposes of the lien.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Vanston Bondholders Protective Committee v. Green","cite":"329 U.S. 156","y":1946,"id":"scdb/1946-010","sc":1,"sum":"In a reorganization proceeding under Chapter X of the Bankruptcy Act, claim was made under a covenant in a first mortgage indenture for interest on interest which had accrued after payments by the debtor corporation had been suspended by a court order in an equity receivership, which was succeeded by a reorganization proceeding under § 77B and later by the Chapter X proceeding. The corporation was insolvent; its …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Viacom International, Inc. v. YouTube, Inc.","cite":"676 F.3d 19","y":2012,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/676/19/","by":{"0":"48"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","subs":["(35A)","(5)"],"stext":{"head":"§101. Definitions","paras":[[0,"In this title the following definitions shall apply:"],[1,"(1) The term \"accountant\" means accountant authorized under applicable law to practice public accounting, and includes professional accounting association, corporation, or partnership, if so authorized."],[1,"(2) The term \"affiliate\" means—"],[2,"(A) entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(B) corporation 20 percent or more of whose outstanding voting securities are directly or indirectly owned, controlled, or held with power to vote, by the debtor, or by an entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(C) person whose business is operated under a lease or operating agreement by a debtor, or person substantially all of whose property is operated under an operating agreement with the debtor; or"],[2,"(D) entity that operates the business or substantially all of the property of the debtor under a lease or operating agreement."],[1,"(3) The term \"assisted person\" means any person whose debts consist primarily of consumer debts and the value of whose nonexempt property is less than $150,000.1"],[1,"(4) The term \"attorney\" means attorney, professional law association, corporation, or partnership, authorized under applicable law to practice law."],[1,"(4A) The term \"bankruptcy assistance\" means any goods or services sold or otherwise provided to an assisted person with the express or implied purpose of providing information, advice, counsel, document preparation, or filing, or attendance at a creditors' meeting or appearing in a case or proceeding on behalf of another or providing legal representation with respect to a case or proceeding under this title."],[1,"(5) The term \"claim\" means—"],[2,"(A) right to payment, whether or not such right is reduced to judgment, liquidated, unliquidated, fixed, contingent, matured, unmatured, disputed, undisputed, legal, equitable, secured, or unsecured; or"],[2,"(B) right to an equitable remedy for breach of performance if such breach gives rise to a right to payment, whether or not such right to an equitable remedy is reduced to judgment, fixed, contingent, matured, unmatured, disputed, undisputed, secured, or unsecured."],[1,"(6) The term \"commodity broker\" means futures commission merchant, foreign futures commission merchant, clearing organization, leverage transaction merchant, or commodity options dealer, as defined in section 761 of this title, with respect to which there is a customer, as defined in section 761 of this title."],[1,"(7) The term \"community claim\" means claim that arose before the commencement of the case concerning the debtor for which property of the kind specified in section 541(a)(2) of this title is liable, whether or not there is any such property at the time of the commencement of the case."],[1,"(7A) The term \"commercial fishing operation\" means—"],[2,"(A) the catching or harvesting of fish, shrimp, lobsters, urchins, seaweed, shellfish, or other aquatic species or products of such species; or"],[2,"(B) for purposes of section 109 and chapter 12, aquaculture activities consisting of raising for market any species or product described in subparagraph (A)."],[1,"(7B) The term \"commercial fishing vessel\" means a vessel used by a family fisherman to carry out a commercial fishing operation."],[1,"(8) The term \"consumer debt\" means debt incurred by an individual primarily for a personal, family, or household purpose."],[1,"(9) The term \"corporation\"—"],[2,"(A) includes—"],[3,"(i) association having a power or privilege that a private corporation, but not an individual or a partnership, possesses;"],[3,"(ii) partnership association organized under a law that makes only the capital subscribed responsible for the debts of such association;"],[3,"(iii) joint-stock company;"],[3,"(iv) unincorporated company or association; or"],[3,"(v) business trust; but"],[2,"(B) does not include limited partnership."],[1,"(10) The term \"creditor\" means—"],[2,"(A) entity that has a claim against the debtor that arose at the time of or before the order for relief concerning the debtor;"],[2,"(B) entity that has a claim against the estate of a kind specified in section 348(d), 502(f), 502(g), 502(h) or 502(i) of this title; or"],[2,"(C) entity that has a community claim."],[1,"(10A) The term \"current monthly income\"—"],[2,"(A) means the average monthly income from all sources that the debtor receives (or in a joint case the debtor and the debtor's spouse receive) without regard to whether such income is taxable income, derived during the 6-month period ending on—"],[3,"(i) the last day of the calendar month immediately preceding the date of the commencement of the case if the debtor files the schedule of current income required by section 521(a)(1)(B)(ii); or"],[3,"(ii) the date on which current income is determined by the court for purposes of this title if the debtor does not file the schedule of current income required by section 521(a)(1)(B)(ii); and"],[2,"(B)(i) includes any amount paid by any entity other than the debtor (or in a joint case the debtor and the debtor's spouse), on a regular basis for the household expenses of the debtor or the debtor's dependents (and in a joint case the debtor's spouse if not otherwise a dependent); and"],[2,"(ii) excludes—"],[3,"(I) benefits received under the Social Security Act (42 U.S.C. 301 et seq.);"],[3,"(II) payments to victims of war crimes or crimes against humanity on account of their status as victims of such crimes;"],[3,"(III) payments to victims of international terrorism or domestic terrorism, as those terms are defined in section 2331 of title 18, on account of their status as victims of such terrorism; and"],[3,"(IV) any monthly compensation, pension, pay, annuity, or allowance paid under title 10, 37, or 38 in connection with a disability, combat-related injury or disability, or death of a member of the uniformed services, except that any retired pay excluded under this subclause shall include retired pay paid under chapter 61 of title 10 only to the extent that such retired pay exceeds the amount of retired pay to which the debtor would otherwise be entitled if retired under any provision of title 10 other than chapter 61 of that title."],[1,"(11) The term \"custodian\" means—"],[2,"(A) receiver or trustee of any of the property of the debtor, appointed in a case or proceeding not under this title;"],[2,"(B) assignee under a general assignment for the benefit of the debtor's creditors; or"],[2,"(C) trustee, receiver, or agent under applicable law, or under a contract, that is appointed or authorized to take charge of property of the debtor for the purpose of enforcing a lien against such property, or for the purpose of general administration of such property for the benefit of the debtor's creditors."],[1,"(12) The term \"debt\" means liability on a claim."],[1,"(12A) The term \"debt relief agency\" means any person who provides any bankruptcy assistance to an assisted person in return for the payment of money or other valuable consideration, or who is a bankruptcy petition preparer under section 110, but does not include—"],[2,"(A) any person who is an officer, director, employee, or agent of a person who provides such assistance or of the bankruptcy petition preparer;"],[2,"(B) a nonprofit organization that is exempt from taxation under section 501(c)(3) of the Internal Revenue Code of 1986;"],[2,"(C) a creditor of such assisted person, to the extent that the creditor is assisting such assisted person to restructure any debt owed by such assisted person to the creditor;"],[2,"(D) a depository institution (as defined in section 3 of the Federal Deposit Insurance Act) or any Federal credit union or State credit union (as those terms are defined in section 101 of the Federal Credit Union Act), or any affiliate or subsidiary of such depository institution or credit union; or"],[2,"(E) an author, publisher, distributor, or seller of works subject to copyright protection under title 17, when acting in such capacity."],[1,"(13) The term \"debtor\" means person or municipality concerning which a case under this title has been commenced."],[1,"(13A) The term \"debtor's principal residence\"—"],[2,"(A) means a residential structure if used as the principal residence by the debtor, including incidental property, without regard to whether that structure is attached to real property; and"],[2,"(B) includes an individual condominium or cooperative unit, a mobile or manufactured home, or trailer if used as the principal residence by the debtor."],[1,"(14) The term \"disinterested person\" means a person that—"],[2,"(A) is not a creditor, an equity security holder, or an insider;"],[2,"(B) is not and was not, within 2 years before the date of the filing of the petition, a director, officer, or employee of the debtor; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/101?type=usc&year=mostrecent&link-type=html"},"head":"§101. Definitions","tname":"Bankruptcy","by":{"0":"45","1":"4, 16, 4, 16","2":"4, 4, 4","3":"5"}},{"t":"usc","label":"15 U.S.C. § 1055","url":"https://www.law.cornell.edu/uscode/text/15/1055","stext":{"head":"§1055. Use by related companies affecting validity and registration","paras":[[0,"Where a registered mark or a mark sought to be registered is or may be used legitimately by related companies, such use shall inure to the benefit of the registrant or applicant for registration, and such use shall not affect the validity of such mark or of its registration, provided such mark is not used in such manner as to deceive the public. If first use of a mark by a person is controlled by the registrant or applicant for registration of the mark with respect to the nature and quality of the goods or services, such first use shall inure to the benefit of the registrant or applicant, as the case may be."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1055?type=usc&year=mostrecent&link-type=html"},"head":"§1055. Use by related companies affecting validity and registration","tname":"Commerce and Trade","by":{"0":"51","2":"9, 45, 54"}},{"t":"usc","label":"28 U.S.C. § 959","url":"https://www.law.cornell.edu/uscode/text/28/959","stext":{"head":"§959. Trustees and receivers suable; management; State laws","paras":[[0,"(a) Trustees, receivers or managers of any property, including debtors in possession, may be sued, without leave of the court appointing them, with respect to any of their acts or transactions in carrying on business connected with such property. Such actions shall be subject to the general equity power of such court so far as the same may be necessary to the ends of justice, but this shall not deprive a litigant of his right to trial by jury."],[0,"(b) Except as provided in section 1166 of title 11, a trustee, receiver or manager appointed in any cause pending in any court of the United States, including a debtor in possession, shall manage and operate the property in his possession as such trustee, receiver or manager according to the requirements of the valid laws of the State in which such property is situated, in the same manner that the owner or possessor thereof would be bound to do if in possession thereof."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/959?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§959. Trustees and receivers suable; management; State laws","tname":"Judiciary and Judicial Procedure","by":{"0":"52"}},{"t":"usc","label":"35 U.S.C. § 154","url":"https://www.law.cornell.edu/uscode/text/35/154","by":{"0":"42"}},{"t":"case","label":"American Brake Shoe & Foundry Co. v. New York Rys. Co.","cite":"278 F. 842","y":1922,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F./278/842/","by":{"1":"22","3":"10"}},{"t":"case","label":"Copeland v. Stephens","cite":"106 Eng. Rep. 218","y":1818,"court":"K.B.","url":"https://www.courtlistener.com/c/Eng.%20Rep./106/218/","by":{"1":"21"}},{"t":"case","label":"Defiance Button Mach. Co. v. C & C Metal Prods. Corp.","cite":"759 F.2d 1053","y":1985,"url":"https://www.courtlistener.com/c/F.2d/759/1053/","by":{"1":"24"}},{"t":"case","label":"Enterprise Energy Corp. v. United States","cite":"50 F.3d 233","y":1995,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/50/233/","by":{"1":"17"}},{"t":"case","label":"Kokoszka v. Belford","cite":"417 U.S. 642","y":1974,"id":"1973/73-5265","sc":1,"sum":"1. An income tax refund is \"property\" that passes to the trustee under § 70a (5) of the Bankruptcy Act, being \"sufficiently rooted in the bankruptcy past,\" and not being related conceptually to or the equivalent of future wages for the purpose of giving the bankrupt wage earner a \"fresh start.\" Lines v. Frederick, 400 U. S. 18, distinguished.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Law v. Siegel","cite":"571 U.S. 415","y":2014,"id":"2013/12-5196","sc":1,"sum":"The Court found that a bankruptcy court may not enforce specific statutory exceptions.","sumSrc":"Oyez","by":{"1":"30","2":"50"}},{"t":"case","label":"Merit Mgmt. Grp., LP v. FTI Consulting, Inc.","cite":"138 S. Ct. 883","y":2018,"id":"2017/16-784","sc":1,"sum":"The Court held that the safe harbor provision of 11 U.S.C. § 546(e), which prohibits a trustee from avoiding a transfer made by or to a financial institution, does not include transfers where the benefit and detriment of the transfer impact companies that are not financial institutions.","sumSrc":"Oyez","by":{"1":"19, 20","2":"49"}},{"t":"case","label":"Midland Funding, LLC v. Johnson","cite":"137 S. Ct. 1407","y":2017,"id":"2016/16-348","sc":1,"sum":"The Court determined that the Fair Debt Collection Practices Act (FDCPA) does not prevent a creditor from filing a proof of claim on an unpaid debt in a Chapter 13 bankruptcy proceeding even after the statute of limitations on that debt has run.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Nautilus, Inc. v. Biosig Instruments, Inc.","cite":"572 U.S. 898","y":2014,"id":"2013/13-369","sc":1,"sum":"The Court held that, although a U.S. patent may be vague in certain areas, it is still protected by patent law as long as the patent is definite enough for the general public to know what has or has not been patented already.","sumSrc":"Oyez","by":{"1":"32","2":"23"}},{"t":"case","label":"O’Neill v. Continental Airlines, Inc.","cite":"981 F.2d 1450","y":1993,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/981/1450/","by":{"1":"18"}},{"t":"case","label":"Sparhawk v. Yerkes","cite":"142 U.S. 1","y":1891,"id":"scdb/1891-043","sc":1,"sum":"In December, 1871, Y., who was a member of the stock exchanges in New York and in Philadelphia, was declared to be a bankrupt. At that time his seat in the New York Exchange was worth about $1000, and the other about $2000. By the rules of each, membership, in case of failure, was suspended until settlement with its members who were creditors, and the seat in each was liable to be sold and the proceeds applied to …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"21, 22"}},{"t":"case","label":"United States Trust Co. v. Wabash W. Ry. Co.","cite":"150 U.S. 287","y":1893,"id":"scdb/1893-040","sc":1,"sum":"On the 10th of February, 1879,-the Council Bluffs and St. Louis Railway Company leased their projected railway from Council Bluffs to the state line to the St. Louis, Kansas City and Northern Railway Company-for the term of 91 years. Together the lines formed the Omaha Division of the Wabash system. On the 15th of February, 1879, the lessee issued bonds to the amount of $2,050,000, secured by a mortgage to the …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Vass v. Conron Bros. Co.","cite":"59 F.2d 969","y":1932,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/59/969/","by":{"1":"22"}},{"t":"case","label":"Watson v. Merrill","cite":"136 F. 359","y":1905,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./136/359/","by":{"1":"21, 22"}},{"t":"law","label":"Pub. L. No. 100-506","url":"https://www.govinfo.gov/link/statute/102/2538","by":{"1":"6"}},{"t":"usc","label":"11 U.S.C. § 323","url":"https://www.law.cornell.edu/uscode/text/11/323","stext":{"head":"§323. Role and capacity of trustee","paras":[[0,"(a) The trustee in a case under this title is the representative of the estate."],[0,"(b) The trustee in a case under this title has capacity to sue and be sued."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/323?type=usc&year=mostrecent&link-type=html"},"head":"§323. Role and capacity of trustee","tname":"Bankruptcy","by":{"1":"4, 16","2":"4"}},{"t":"usc","label":"11 U.S.C. § 365","url":"https://www.law.cornell.edu/uscode/text/11/365","subs":["(a)","(g)","(g)(1)","(h)","(n)","(n)(1)","(n)(2)(B)","(d)","(d)(1)","(h)(1)","(h)(l)(B)","(h)(l)(C)","(h)(2)","(i)","(i)(1)","(i)(2)","(n)(1)(B)","(n)(2)","(n)(2)(C)"],"stext":{"head":"§365. Executory contracts and unexpired leases","paras":[[0,"(a) Except as provided in sections 765 and 766 of this title and in subsections (b), (c), and (d) of this section, the trustee, subject to the court's approval, may assume or reject any executory contract or unexpired lease of the debtor."],[0,"(b)(1) If there has been a default in an executory contract or unexpired lease of the debtor, the trustee may not assume such contract or lease unless, at the time of assumption of such contract or lease, the trustee—"],[1,"(A) cures, or provides adequate assurance that the trustee will promptly cure, such default other than a default that is a breach of a provision relating to the satisfaction of any provision (other than a penalty rate or penalty provision) relating to a default arising from any failure to perform nonmonetary obligations under an unexpired lease of real property, if it is impossible for the trustee to cure such default by performing nonmonetary acts at and after the time of assumption, except that if such default arises from a failure to operate in accordance with a nonresidential real property lease, then such default shall be cured by performance at and after the time of assumption in accordance with such lease, and pecuniary losses resulting from such default shall be compensated in accordance with the provisions of this paragraph;"],[1,"(B) compensates, or provides adequate assurance that the trustee will promptly compensate, a party other than the debtor to such contract or lease, for any actual pecuniary loss to such party resulting from such default; and"],[1,"(C) provides adequate assurance of future performance under such contract or lease."],[0,"(2) Paragraph (1) of this subsection does not apply to a default that is a breach of a provision relating to—"],[1,"(A) the insolvency or financial condition of the debtor at any time before the closing of the case;"],[1,"(B) the commencement of a case under this title;"],[1,"(C) the appointment of or taking possession by a trustee in a case under this title or a custodian before such commencement; or"],[1,"(D) the satisfaction of any penalty rate or penalty provision relating to a default arising from any failure by the debtor to perform nonmonetary obligations under the executory contract or unexpired lease."],[0,"(3) For the purposes of paragraph (1) of this subsection and paragraph (2)(B) of subsection (f), adequate assurance of future performance of a lease of real property in a shopping center includes adequate assurance—"],[1,"(A) of the source of rent and other consideration due under such lease, and in the case of an assignment, that the financial condition and operating performance of the proposed assignee and its guarantors, if any, shall be similar to the financial condition and operating performance of the debtor and its guarantors, if any, as of the time the debtor became the lessee under the lease;"],[1,"(B) that any percentage rent due under such lease will not decline substantially;"],[1,"(C) that assumption or assignment of such lease is subject to all the provisions thereof, including (but not limited to) provisions such as a radius, location, use, or exclusivity provision, and will not breach any such provision contained in any other lease, financing agreement, or master agreement relating to such shopping center; and"],[1,"(D) that assumption or assignment of such lease will not disrupt any tenant mix or balance in such shopping center."],[0,"(4) Notwithstanding any other provision of this section, if there has been a default in an unexpired lease of the debtor, other than a default of a kind specified in paragraph (2) of this subsection, the trustee may not require a lessor to provide services or supplies incidental to such lease before assumption of such lease unless the lessor is compensated under the terms of such lease for any services and supplies provided under such lease before assumption of such lease."],[0,"(c) The trustee may not assume or assign any executory contract or unexpired lease of the debtor, whether or not such contract or lease prohibits or restricts assignment of rights or delegation of duties, if—"],[1,"(1)(A) applicable law excuses a party, other than the debtor, to such contract or lease from accepting performance from or rendering performance to an entity other than the debtor or the debtor in possession, whether or not such contract or lease prohibits or restricts assignment of rights or delegation of duties; and"],[1,"(B) such party does not consent to such assumption or assignment; or"],[1,"(2) such contract is a contract to make a loan, or extend other debt financing or financial accommodations, to or for the benefit of the debtor, or to issue a security of the debtor; or"],[1,"(3) such lease is of nonresidential real property and has been terminated under applicable nonbankruptcy law prior to the order for relief."],[0,"(d)(1) In a case under chapter 7 of this title, if the trustee does not assume or reject an executory contract or unexpired lease of residential real property or of personal property of the debtor within 60 days after the order for relief, or within such additional time as the court, for cause, within such 60-day period, fixes, then such contract or lease is deemed rejected."],[0,"(2) In a case under chapter 9, 11, 12, or 13 of this title, the trustee may assume or reject an executory contract or unexpired lease of residential real property or of personal property of the debtor at any time before the confirmation of a plan but the court, on the request of any party to such contract or lease, may order the trustee to determine within a specified period of time whether to assume or reject such contract or lease."],[0,"(3) The trustee shall timely perform all the obligations of the debtor, except those specified in section 365(b)(2), arising from and after the order for relief under any unexpired lease of nonresidential real property, until such lease is assumed or rejected, notwithstanding section 503(b)(1) of this title. The court may extend, for cause, the time for performance of any such obligation that arises within 60 days after the date of the order for relief, but the time for performance shall not be extended beyond such 60-day period. This subsection shall not be deemed to affect the trustee's obligations under the provisions of subsection (b) or (f) of this section. Acceptance of any such performance does not constitute waiver or relinquishment of the lessor's rights under such lease or under this title."],[0,"(4)(A) Subject to subparagraph (B), an unexpired lease of nonresidential real property under which the debtor is the lessee shall be deemed rejected, and the trustee shall immediately surrender that nonresidential real property to the lessor, if the trustee does not assume or reject the unexpired lease by the earlier of—"],[1,"(i) the date that is 120 days after the date of the order for relief; or"],[1,"(ii) the date of the entry of an order confirming a plan."],[0,"(B)(i) The court may extend the period determined under subparagraph (A), prior to the expiration of the 120-day period, for 90 days on the motion of the trustee or lessor for cause."],[0,"(ii) If the court grants an extension under clause (i), the court may grant a subsequent extension only upon prior written consent of the lessor in each instance."],[0,"(5) The trustee shall timely perform all of the obligations of the debtor, except those specified in section 365(b)(2), first arising from or after 60 days after the order for relief in a case under chapter 11 of this title under an unexpired lease of personal property (other than personal property leased to an individual primarily for personal, family, or household purposes), until such lease is assumed or rejected notwithstanding section 503(b)(1) of this title, unless the court, after notice and a hearing and based on the equities of the case, orders otherwise with respect to the obligations or timely performance thereof. This subsection shall not be deemed to affect the trustee's obligations under the provisions of subsection (b) or (f). Acceptance of any such performance does not constitute waiver or relinquishment of the lessor's rights under such lease or under this title."],[0,"(e)(1) Notwithstanding a provision in an executory contract or unexpired lease, or in applicable law, an executory contract or unexpired lease of the debtor may not be terminated or modified, and any right or obligation under such contract or lease may not be terminated or modified, at any time after the commencement of the case solely because of a provision in such contract or lease that is conditioned on—"],[1,"(A) the insolvency or financial condition of the debtor at any time before the closing of the case;"],[1,"(B) the commencement of a case under this title; or"],[1,"(C) the appointment of or taking possession by a trustee in a case under this title or a custodian before such commencement."],[0,"(2) Paragraph (1) of this subsection does not apply to an executory contract or unexpired lease of the debtor, whether or not such contract or lease prohibits or restricts assignment of rights or delegation of duties, if—"],[1,"(A)(i) applicable law excuses a party, other than the debtor, to such contract or lease from accepting performance from or rendering performance to the trustee or to an assignee of such contract or lease, whether or not such contract or lease prohibits or restricts assignment of rights or delegation of duties; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/365?type=usc&year=mostrecent&link-type=html"},"op":20,"ar":2,"head":"§365. Executory contracts and unexpired leases","tname":"Bankruptcy","by":{"1":"27, 27, 27, 27, 27, 4, 4, 4","2":"passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, 32, 32, 32, 32, 32, 32"}},{"t":"usc","label":"11 U.S.C. § 541","url":"https://www.law.cornell.edu/uscode/text/11/541","subs":["(a)"],"stext":{"head":"§541. Property of the estate","paras":[[0,"(a) The commencement of a case under section 301, 302, or 303 of this title creates an estate. Such estate is comprised of all the following property, wherever located and by whomever held:"],[1,"(1) Except as provided in subsections (b) and (c)(2) of this section, all legal or equitable interests of the debtor in property as of the commencement of the case."],[1,"(2) All interests of the debtor and the debtor's spouse in community property as of the commencement of the case that is—"],[2,"(A) under the sole, equal, or joint management and control of the debtor; or"],[2,"(B) liable for an allowable claim against the debtor, or for both an allowable claim against the debtor and an allowable claim against the debtor's spouse, to the extent that such interest is so liable."],[1,"(3) Any interest in property that the trustee recovers under section 329(b), 363(n), 543, 550, 553, or 723 of this title."],[1,"(4) Any interest in property preserved for the benefit of or ordered transferred to the estate under section 510(c) or 551 of this title."],[1,"(5) Any interest in property that would have been property of the estate if such interest had been an interest of the debtor on the date of the filing of the petition, and that the debtor acquires or becomes entitled to acquire within 180 days after such date—"],[2,"(A) by bequest, devise, or inheritance;"],[2,"(B) as a result of a property settlement agreement with the debtor's spouse, or of an interlocutory or final divorce decree; or"],[2,"(C) as a beneficiary of a life insurance policy or of a death benefit plan."],[1,"(6) Proceeds, product, offspring, rents, or profits of or from property of the estate, except such as are earnings from services performed by an individual debtor after the commencement of the case."],[1,"(7) Any interest in property that the estate acquires after the commencement of the case."],[0,"(b) Property of the estate does not include—"],[1,"(1) any power that the debtor may exercise solely for the benefit of an entity other than the debtor;"],[1,"(2) any interest of the debtor as a lessee under a lease of nonresidential real property that has terminated at the expiration of the stated term of such lease before the commencement of the case under this title, and ceases to include any interest of the debtor as a lessee under a lease of nonresidential real property that has terminated at the expiration of the stated term of such lease during the case;"],[1,"(3) any eligibility of the debtor to participate in programs authorized under the Higher Education Act of 1965 (20 U.S.C. 1001 et seq.; 42 U.S.C. 2751 et seq.),1 or any accreditation status or State licensure of the debtor as an educational institution;"],[1,"(4) any interest of the debtor in liquid or gaseous hydrocarbons to the extent that—"],[2,"(A)(i) the debtor has transferred or has agreed to transfer such interest pursuant to a farmout agreement or any written agreement directly related to a farmout agreement; and"],[2,"(ii) but for the operation of this paragraph, the estate could include the interest referred to in clause (i) only by virtue of section 365 or 544(a)(3) of this title; or"],[2,"(B)(i) the debtor has transferred such interest pursuant to a written conveyance of a production payment to an entity that does not participate in the operation of the property from which such production payment is transferred; and"],[2,"(ii) but for the operation of this paragraph, the estate could include the interest referred to in clause (i) only by virtue of section 365 or 542 of this title;"],[1,"(5) funds placed in an education individual retirement account (as defined in section 530(b)(1) of the Internal Revenue Code of 1986) not later than 365 days before the date of the filing of the petition in a case under this title, but—"],[2,"(A) only if the designated beneficiary of such account was a child, stepchild, grandchild, or stepgrandchild of the debtor for the taxable year for which funds were placed in such account;"],[2,"(B) only to the extent that such funds—"],[3,"(i) are not pledged or promised to any entity in connection with any extension of credit; and"],[3,"(ii) are not excess contributions (as described in section 4973(e) of the Internal Revenue Code of 1986); and"],[2,"(C) in the case of funds placed in all such accounts having the same designated beneficiary not earlier than 720 days nor later than 365 days before such date, only so much of such funds as does not exceed $5,000; 2"],[1,"(6) funds used to purchase a tuition credit or certificate or contributed to an account in accordance with section 529(b)(1)(A) of the Internal Revenue Code of 1986 under a qualified State tuition program (as defined in section 529(b)(1) of such Code) not later than 365 days before the date of the filing of the petition in a case under this title, but—"],[2,"(A) only if the designated beneficiary of the amounts paid or contributed to such tuition program was a child, stepchild, grandchild, or stepgrandchild of the debtor for the taxable year for which funds were paid or contributed;"],[2,"(B) with respect to the aggregate amount paid or contributed to such program having the same designated beneficiary, only so much of such amount as does not exceed the total contributions permitted under section 529(b)(6) of such Code with respect to such beneficiary, as adjusted beginning on the date of the filing of the petition in a case under this title by the annual increase or decrease (rounded to the nearest tenth of 1 percent) in the education expenditure category of the Consumer Price Index prepared by the Department of Labor; and"],[2,"(C) in the case of funds paid or contributed to such program having the same designated beneficiary not earlier than 720 days nor later than 365 days before such date, only so much of such funds as does not exceed $5,000; 2"],[1,"(7) any amount—"],[2,"(A) withheld by an employer from the wages of employees for payment as contributions—"],[3,"(i) to—"],[4,"(I) an employee benefit plan that is subject to title I of the Employee Retirement Income Security Act of 1974 or under an employee benefit plan which is a governmental plan under section 414(d) of the Internal Revenue Code of 1986;"],[4,"(II) a deferred compensation plan under section 457 of the Internal Revenue Code of 1986; or"],[4,"(III) a tax-deferred annuity under section 403(b) of the Internal Revenue Code of 1986;"],[0,"except that such amount under this subparagraph shall not constitute disposable income as defined in section 1325(b)(2); or"],[3,"(ii) to a health insurance plan regulated by State law whether or not subject to such title; or"],[2,"(B) received by an employer from employees for payment as contributions—"],[3,"(i) to—"],[4,"(I) an employee benefit plan that is subject to title I of the Employee Retirement Income Security Act of 1974 or under an employee benefit plan which is a governmental plan under section 414(d) of the Internal Revenue Code of 1986;"],[4,"(II) a deferred compensation plan under section 457 of the Internal Revenue Code of 1986; or"],[4,"(III) a tax-deferred annuity under section 403(b) of the Internal Revenue Code of 1986;"],[0,"except that such amount under this subparagraph shall not constitute disposable income, as defined in section 1325(b)(2); or"],[3,"(ii) to a health insurance plan regulated by State law whether or not subject to such title;"],[1,"(8) subject to subchapter III of chapter 5, any interest of the debtor in property where the debtor pledged or sold tangible personal property (other than securities or written or printed evidences of indebtedness or title) as collateral for a loan or advance of money given by a person licensed under law to make such loans or advances, where—"],[2,"(A) the tangible personal property is in the possession of the pledgee or transferee;"],[2,"(B) the debtor has no obligation to repay the money, redeem the collateral, or buy back the property at a stipulated price; and"],[2,"(C) neither the debtor nor the trustee have exercised any right to redeem provided under the contract or State law, in a timely manner as provided under State law and section 108(b);"],[1,"(9) any interest in cash or cash equivalents that constitute proceeds of a sale by the debtor of a money order that is made—"],[2,"(A) on or after the date that is 14 days prior to the date on which the petition is filed; and"],[2,"(B) under an agreement with a money order issuer that prohibits the commingling of such proceeds with property of the debtor (notwithstanding that, contrary to the agreement, the proceeds may have been commingled with property of the debtor),"],[1,"unless the money order issuer had not taken action, prior to the filing of the petition, to require compliance with the prohibition; or"],[1,"(10) funds placed in an account of a qualified ABLE program (as defined in section 529A(b) of the Internal Revenue Code of 1986) not later than 365 days before the date of the filing of the petition in a case under this title, but—"],[2,"(A) only if the designated beneficiary of such account was a child, stepchild, grandchild, or stepgrandchild of the debtor for the taxable year for which funds were placed in such account;"],[2,"(B) only to the extent that such funds—"],[3,"(i) are not pledged or promised to any entity in connection with any extension of credit; and"],[3,"(ii) are not excess contributions (as described in section 4973(h) of the Internal Revenue Code of 1986); and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/541?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§541. Property of the estate","tname":"Bankruptcy","by":{"1":"4","2":"4"}},{"t":"usc","label":"11 U.S.C. § 544","url":"https://www.law.cornell.edu/uscode/text/11/544","stext":{"head":"§544. Trustee as lien creditor and as successor to certain creditors and purchasers","paras":[[0,"(a) The trustee shall have, as of the commencement of the case, and without regard to any knowledge of the trustee or of any creditor, the rights and powers of, or may avoid any transfer of property of the debtor or any obligation incurred by the debtor that is voidable by—"],[1,"(1) a creditor that extends credit to the debtor at the time of the commencement of the case, and that obtains, at such time and with respect to such credit, a judicial lien on all property on which a creditor on a simple contract could have obtained such a judicial lien, whether or not such a creditor exists;"],[1,"(2) a creditor that extends credit to the debtor at the time of the commencement of the case, and obtains, at such time and with respect to such credit, an execution against the debtor that is returned unsatisfied at such time, whether or not such a creditor exists; or"],[1,"(3) a bona fide purchaser of real property, other than fixtures, from the debtor, against whom applicable law permits such transfer to be perfected, that obtains the status of a bona fide purchaser and has perfected such transfer at the time of the commencement of the case, whether or not such a purchaser exists."],[0,"(b)(1) Except as provided in paragraph (2), the trustee may avoid any transfer of an interest of the debtor in property or any obligation incurred by the debtor that is voidable under applicable law by a creditor holding an unsecured claim that is allowable under section 502 of this title or that is not allowable only under section 502(e) of this title."],[0,"(2) Paragraph (1) shall not apply to a transfer of a charitable contribution (as that term is defined in section 548(d)(3)) that is not covered under section 548(a)(1)(B), by reason of section 548(a)(2). Any claim by any person to recover a transferred contribution described in the preceding sentence under Federal or State law in a Federal or State court shall be preempted by the commencement of the case."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/544?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§544. Trustee as lien creditor and as successor to certain creditors and purchasers","tname":"Bankruptcy","by":{"1":"19"}},{"t":"usc","label":"11 U.S.C. § 546","url":"https://www.law.cornell.edu/uscode/text/11/546","subs":["(a)","(b)"],"by":{"1":"20, 20"}},{"t":"usc","label":"11 U.S.C. § 548","url":"https://www.law.cornell.edu/uscode/text/11/548","subs":["(a)","(a)(1)(A)"],"by":{"1":"19, 20"}},{"t":"usc","label":"11 U.S.C. § 550","url":"https://www.law.cornell.edu/uscode/text/11/550","subs":["(a)"],"by":{"1":"20"}},{"t":"usc","label":"11 U.S.C. § 553","url":"https://www.law.cornell.edu/uscode/text/11/553","by":{"1":"19"}},{"t":"usc","label":"11 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/11/1101","subs":["(1)"],"stext":{"head":"§1101. Definitions for this chapter","paras":[[0,"In this chapter—"],[1,"(1) \"debtor in possession\" means debtor except when a person that has qualified under section 322 of this title is serving as trustee in the case;"],[1,"(2) \"substantial consummation\" means—"],[2,"(A) transfer of all or substantially all of the property proposed by the plan to be transferred;"],[2,"(B) assumption by the debtor or by the successor to the debtor under the plan of the business or of the management of all or substantially all of the property dealt with by the plan; and"],[2,"(C) commencement of distribution under the plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1101?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1101. Definitions for this chapter","tname":"Bankruptcy","by":{"1":"4, 4, 6, 15, 16, 26","2":"4"}},{"t":"usc","label":"11 U.S.C. § 1107","url":"https://www.law.cornell.edu/uscode/text/11/1107","subs":["(a)"],"stext":{"head":"§1107. Rights, powers, and duties of debtor in possession","paras":[[0,"(a) Subject to any limitations on a trustee serving in a case under this chapter, and to such limitations or conditions as the court prescribes, a debtor in possession shall have all the rights, other than the right to compensation under section 330 of this title, and powers, and shall perform all the functions and duties, except the duties specified in sections 1106(a)(2), (3), and (4) of this title, of a trustee serving in a case under this chapter."],[0,"(b) Notwithstanding section 327(a) of this title, a person is not disqualified for employment under section 327 of this title by a debtor in possession solely because of such person's employment by or representation of the debtor before the commencement of the case."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1107?type=usc&year=mostrecent&link-type=html"},"head":"§1107. Rights, powers, and duties of debtor in possession","tname":"Bankruptcy","by":{"1":"4","2":"4"}},{"t":"usc","label":"15 U.S.C. § 1051","url":"https://www.law.cornell.edu/uscode/text/15/1051","stext":{"head":"§1051. Application for registration; verification","paras":[[0,"(a) Application for use of trademark"],[0,"(1) The owner of a trademark used in commerce may request registration of its trademark on the principal register hereby established by paying the prescribed fee and filing in the Patent and Trademark Office an application and a verified statement, in such form as may be prescribed by the Director, and such number of specimens or facsimiles of the mark as used as may be required by the Director."],[0,"(2) The application shall include specification of the applicant's domicile and citizenship, the date of the applicant's first use of the mark, the date of the applicant's first use of the mark in commerce, the goods in connection with which the mark is used, and a drawing of the mark."],[0,"(3) The statement shall be verified by the applicant and specify that—"],[1,"(A) the person making the verification believes that he or she, or the juristic person in whose behalf he or she makes the verification, to be the owner of the mark sought to be registered;"],[1,"(B) to the best of the verifier's knowledge and belief, the facts recited in the application are accurate;"],[1,"(C) the mark is in use in commerce; and"],[1,"(D) to the best of the verifier's knowledge and belief, no other person has the right to use such mark in commerce either in the identical form thereof or in such near resemblance thereto as to be likely, when used on or in connection with the goods of such other person, to cause confusion, or to cause mistake, or to deceive, except that, in the case of every application claiming concurrent use, the applicant shall—"],[2,"(i) state exceptions to the claim of exclusive use; and"],[2,"(ii) shall 1 specify, to the extent of the verifier's knowledge—"],[3,"(I) any concurrent use by others;"],[3,"(II) the goods on or in connection with which and the areas in which each concurrent use exists;"],[3,"(III) the periods of each use; and"],[3,"(IV) the goods and area for which the applicant desires registration."],[0,"(4) The applicant shall comply with such rules or regulations as may be prescribed by the Director. The Director shall promulgate rules prescribing the requirements for the application and for obtaining a filing date herein."],[0,"(b) Application for bona fide intention to use trademark"],[0,"(1) A person who has a bona fide intention, under circumstances showing the good faith of such person, to use a trademark in commerce may request registration of its trademark on the principal register hereby established by paying the prescribed fee and filing in the Patent and Trademark Office an application and a verified statement, in such form as may be prescribed by the Director."],[0,"(2) The application shall include specification of the applicant's domicile and citizenship, the goods in connection with which the applicant has a bona fide intention to use the mark, and a drawing of the mark."],[0,"(3) The statement shall be verified by the applicant and specify—"],[1,"(A) that the person making the verification believes that he or she, or the juristic person in whose behalf he or she makes the verification, to be entitled to use the mark in commerce;"],[1,"(B) the applicant's bona fide intention to use the mark in commerce;"],[1,"(C) that, to the best of the verifier's knowledge and belief, the facts recited in the application are accurate; and"],[1,"(D) that, to the best of the verifier's knowledge and belief, no other person has the right to use such mark in commerce either in the identical form thereof or in such near resemblance thereto as to be likely, when used on or in connection with the goods of such other person, to cause confusion, or to cause mistake, or to deceive."],[0,"Except for applications filed pursuant to section 1126 of this title, no mark shall be registered until the applicant has met the requirements of subsections (c) and (d) of this section."],[0,"(4) The applicant shall comply with such rules or regulations as may be prescribed by the Director. The Director shall promulgate rules prescribing the requirements for the application and for obtaining a filing date herein."],[0,"(c) Amendment of application under subsection (b) to conform to requirements of subsection (a)"],[0,"At any time during examination of an application filed under subsection (b), an applicant who has made use of the mark in commerce may claim the benefits of such use for purposes of this chapter, by amending his or her application to bring it into conformity with the requirements of subsection (a)."],[0,"(d) Verified statement that trademark is used in commerce"],[0,"(1) Within six months after the date on which the notice of allowance with respect to a mark is issued under section 1063(b)(2) of this title to an applicant under subsection (b) of this section, the applicant shall file in the Patent and Trademark Office, together with such number of specimens or facsimiles of the mark as used in commerce as may be required by the Director and payment of the prescribed fee, a verified statement that the mark is in use in commerce and specifying the date of the applicant's first use of the mark in commerce and those goods or services specified in the notice of allowance on or in connection with which the mark is used in commerce. Subject to examination and acceptance of the statement of use, the mark shall be registered in the Patent and Trademark Office, a certificate of registration shall be issued for those goods or services recited in the statement of use for which the mark is entitled to registration, and notice of registration shall be published in the Official Gazette of the Patent and Trademark Office. Such examination may include an examination of the factors set forth in subsections (a) through (e) of section 1052 of this title. The notice of registration shall specify the goods or services for which the mark is registered."],[0,"(2) The Director shall extend, for one additional 6-month period, the time for filing the statement of use under paragraph (1), upon written request of the applicant before the expiration of the 6-month period provided in paragraph (1). In addition to an extension under the preceding sentence, the Director may, upon a showing of good cause by the applicant, further extend the time for filing the statement of use under paragraph (1) for periods aggregating not more than 24 months, pursuant to written request of the applicant made before the expiration of the last extension granted under this paragraph. Any request for an extension under this paragraph shall be accompanied by a verified statement that the applicant has a continued bona fide intention to use the mark in commerce and specifying those goods or services identified in the notice of allowance on or in connection with which the applicant has a continued bona fide intention to use the mark in commerce. Any request for an extension under this paragraph shall be accompanied by payment of the prescribed fee. The Director shall issue regulations setting forth guidelines for determining what constitutes good cause for purposes of this paragraph."],[0,"(3) The Director shall notify any applicant who files a statement of use of the acceptance or refusal thereof and, if the statement of use is refused, the reasons for the refusal. An applicant may amend the statement of use."],[0,"(4) The failure to timely file a verified statement of use under paragraph (1) or an extension request under paragraph (2) shall result in abandonment of the application, unless it can be shown to the satisfaction of the Director that the delay in responding was unintentional, in which case the time for filing may be extended, but for a period not to exceed the period specified in paragraphs (1) and (2) for filing a statement of use."],[0,"(e) Designation of resident for service of process and notices"],[0,"If the applicant is not domiciled in the United States the applicant may designate, by a document filed in the United States Patent and Trademark Office, the name and address of a person resident in the United States on whom may be served notices or process in proceedings affecting the mark. Such notices or process may be served upon the person so designated by leaving with that person or mailing to that person a copy thereof at the address specified in the last designation so filed. If the person so designated cannot be found at the address given in the last designation, or if the registrant does not designate by a document filed in the United States Patent and Trademark Office the name and address of a person resident in the United States on whom may be served notices or process in proceedings affecting the mark, such notices or process may be served on the Director."],[0,"(f) Third-party submission of evidence"],[0,"A third party may submit for consideration for inclusion in the record of an application evidence relevant to a ground for refusal of registration. The third-party submission shall identify the ground for refusal and include a concise description of each piece of evidence submitted in support of each identified ground for refusal. Not later than 2 months after the date on which the submission is filed, the Director shall determine whether the evidence should be included in the record of the application. The Director shall establish by regulation appropriate procedures for the consideration of evidence submitted by a third party under this subsection and may prescribe a fee to accompany the submission. If the Director determines that the third-party evidence should be included in the record of the application, only the evidence and the ground for refusal to which the evidence relates may be so included. Any determination by the Director whether or not to include evidence in the record of an application shall be final and non-reviewable, and a determination to include or to not include evidence in the record shall not prejudice any party's right to raise any issue and rely on any evidence in any other proceeding."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1051?type=usc&year=mostrecent&link-type=html"},"head":"§1051. Application for registration; verification","tname":"Commerce and Trade","by":{"1":"2","2":"8, 9, 53"}},{"t":"usc","label":"15 U.S.C. § 1127","url":"https://www.law.cornell.edu/uscode/text/15/1127","stext":{"head":"§1127. Construction and definitions; intent of chapter","paras":[[0,"In the construction of this chapter, unless the contrary is plainly apparent from the context—"],[0,"The United States includes and embraces all territory which is under its jurisdiction and control."],[0,"The word \"commerce\" means all commerce which may lawfully be regulated by Congress."],[0,"The term \"principal register\" refers to the register provided for by sections 1051 to 1072 of this title, and the term \"supplemental register\" refers to the register provided for by sections 1091 to 1096 of this title."],[0,"The term \"person\" and any other word or term used to designate the applicant or other entitled to a benefit or privilege or rendered liable under the provisions of this chapter includes a juristic person as well as a natural person. The term \"juristic person\" includes a firm, corporation, union, association, or other organization capable of suing and being sued in a court of law."],[0,"The term \"person\" also includes the United States, any agency or instrumentality thereof, or any individual, firm, or corporation acting for the United States and with the authorization and consent of the United States. The United States, any agency or instrumentality thereof, and any individual, firm, or corporation acting for the United States and with the authorization and consent of the United States, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"The term \"person\" also includes any State, any instrumentality of a State, and any officer or employee of a State or instrumentality of a State acting in his or her official capacity. Any State, and any such instrumentality, officer, or employee, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"The terms \"applicant\" and \"registrant\" embrace the legal representatives, predecessors, successors and assigns of such applicant or registrant."],[0,"The term \"Director\" means the Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office."],[0,"The term \"related company\" means any person whose use of a mark is controlled by the owner of the mark with respect to the nature and quality of the goods or services on or in connection with which the mark is used."],[0,"The terms \"trade name\" and \"commercial name\" mean any name used by a person to identify his or her business or vocation."],[0,"The term \"trademark\" includes any word, name, symbol, or device, or any combination thereof—"],[1,"(1) used by a person, or"],[1,"(2) which a person has a bona fide intention to use in commerce and applies to register on the principal register established by this chapter,"],[0,"to identify and distinguish his or her goods, including a unique product, from those manufactured or sold by others and to indicate the source of the goods, even if that source is unknown."],[0,"The term \"service mark\" means any word, name, symbol, or device, or any combination thereof—"],[1,"(1) used by a person, or"],[1,"(2) which a person has a bona fide intention to use in commerce and applies to register on the principal register established by this chapter,"],[0,"to identify and distinguish the services of one person, including a unique service, from the services of others and to indicate the source of the services, even if that source is unknown. Titles, character names, and other distinctive features of radio or television programs may be registered as service marks notwithstanding that they, or the programs, may advertise the goods of the sponsor."],[0,"The term \"certification mark\" means any word, name, symbol, or device, or any combination thereof—"],[1,"(1) used by a person other than its owner, or"],[1,"(2) which its owner has a bona fide intention to permit a person other than the owner to use in commerce and files an application to register on the principal register established by this chapter,"],[0,"to certify regional or other origin, material, mode of manufacture, quality, accuracy, or other characteristics of such person's goods or services or that the work or labor on the goods or services was performed by members of a union or other organization."],[0,"The term \"collective mark\" means a trademark or service mark—"],[1,"(1) used by the members of a cooperative, an association, or other collective group or organization, or"],[1,"(2) which such cooperative, association, or other collective group or organization has a bona fide intention to use in commerce and applies to register on the principal register established by this chapter,"],[0,"and includes marks indicating membership in a union, an association, or other organization."],[0,"The term \"mark\" includes any trademark, service mark, collective mark, or certification mark."],[0,"The term \"use in commerce\" means the bona fide use of a mark in the ordinary course of trade, and not made merely to reserve a right in a mark. For purposes of this chapter, a mark shall be deemed to be in use in commerce—"],[1,"(1) on goods when—"],[2,"(A) it is placed in any manner on the goods or their containers or the displays associated therewith or on the tags or labels affixed thereto, or if the nature of the goods makes such placement impracticable, then on documents associated with the goods or their sale, and"],[2,"(B) the goods are sold or transported in commerce, and"],[1,"(2) on services when it is used or displayed in the sale or advertising of services and the services are rendered in commerce, or the services are rendered in more than one State or in the United States and a foreign country and the person rendering the services is engaged in commerce in connection with the services."],[0,"A mark shall be deemed to be \"abandoned\" if either of the following occurs:"],[1,"(1) When its use has been discontinued with intent not to resume such use. Intent not to resume may be inferred from circumstances. Nonuse for 3 consecutive years shall be prima facie evidence of abandonment. \"Use\" of a mark means the bona fide use of such mark made in the ordinary course of trade, and not made merely to reserve a right in a mark."],[1,"(2) When any course of conduct of the owner, including acts of omission as well as commission, causes the mark to become the generic name for the goods or services on or in connection with which it is used or otherwise to lose its significance as a mark. Purchaser motivation shall not be a test for determining abandonment under this paragraph."],[0,"The term \"colorable imitation\" includes any mark which so resembles a registered mark as to be likely to cause confusion or mistake or to deceive."],[0,"The term \"registered mark\" means a mark registered in the United States Patent and Trademark Office under this chapter or under the Act of March 3, 1881, or the Act of February 20, 1905, or the Act of March 19, 1920. The phrase \"marks registered in the Patent and Trademark Office\" means registered marks."],[0,"The term \"Act of March 3, 1881\", \"Act of February 20, 1905\", or \"Act of March 19, 1920\", means the respective Act as amended."],[0,"A \"counterfeit\" is a spurious mark which is identical with, or substantially indistinguishable from, a registered mark."],[0,"The term \"domain name\" means any alphanumeric designation which is registered with or assigned by any domain name registrar, domain name registry, or other domain name registration authority as part of an electronic address on the Internet."],[0,"The term \"Internet\" has the meaning given that term in section 230(f)(1) of title 47."],[0,"Words used in the singular include the plural and vice versa."],[0,"The intent of this chapter is to regulate commerce within the control of Congress by making actionable the deceptive and misleading use of marks in such commerce; to protect registered marks used in such commerce from interference by State, or territorial legislation; to protect persons engaged in such commerce against unfair competition; to prevent fraud and deception in such commerce by the use of reproductions, copies, counterfeits, or colorable imitations of registered marks; and to provide rights and remedies stipulated by treaties and conventions respecting trademarks, trade names, and unfair competition entered into between the United States and foreign nations."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1127?type=usc&year=mostrecent&link-type=html"},"head":"§1127. Construction and definitions; intent of chapter","tname":"Commerce and Trade","by":{"1":"14","2":"9, 45, 58"}},{"t":"usc","label":"28 U.S.C. § 581-589a","url":"https://www.law.cornell.edu/uscode/text/28/581-589a","by":{"1":"2"}},{"t":"case","label":"Andrus v. Glover Constr. Co.","cite":"446 U.S. 608","y":1980,"id":"1979/79-48","sc":1,"sum":"Held.: The Buy Indian Act, which permits the Secretary of the Interior to purchase \"the products of Indian industry... in open market,\" does not authorize the Department of the Interior's Bureau of Indian Affairs (BIA) to enter into road construction contracts with Indianowned companies without first advertising for bids pursuant to Title III of the Federal Property and Administrative Services Act of 1949 (FPASA). …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"38"}},{"t":"case","label":"B & B Hardware, Inc. v. Hargis Indus., Inc.","cite":"135 S. Ct. 1293","y":2015,"id":"2014/13-352","sc":1,"sum":"The Court held that a decision on an issue by an administrative agency can preclude re-litigation of that issue in federal court.","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"Bank of Am. Nat’l Tr. & Sav. Ass’n v. 203 N. LaSalle St. P’ship","cite":"526 U.S. 434","y":1999,"id":"1998/97-1418","sc":1,"sum":"A debtor's prebankruptcy equity holders may not contribute new capital and receive ownership in the debtor's reorganization entity","sumSrc":"Oyez","by":{"2":"41"}},{"t":"case","label":"Begier v. IRS","cite":"496 U.S. 53","y":1990,"id":"1989/89-393","sc":1,"sum":"AIA's trust-fund tax payments from its general accounts were transfers of property held in trust and therefore cannot be avoided as preferences.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42"}},{"t":"case","label":"Church of Scientology v. United States","cite":"506 U.S. 9","y":1992,"id":"1992/91-946","sc":1,"sum":"Compliance with the summons enforcement order did not moot the Church's appeal. Delivery of the tapes to the IRS did not mandate dismissal by making it impossible for the Court of Appeals to grant the Church \"any effectual relief.\" See Mills v. Green, 159 U. S. 651, 653. Although it is now too late to prevent, or to provide a fully satisfactory remedy for, the invasion of privacy that occurred when the IRS obtained …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"City Bank Farmers Tr. Co. v. Irving Tr. Co.","cite":"299 U.S. 433","y":1937,"id":"scdb/1936-079","sc":1,"sum":"That the lessor, in a lease having no covenant upon the part of the lessee to indemnify against or pay damages arising out of its termination, was a \"person injured\" by the rejection of the lease by the lessee's trustee in bankruptcy; and in a subsequent proceeding under § 77B has a provable claim against the debtor's estate for the injury, even assuming that the lessor's reentry, reletting, and restoration of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"passim","3":"5"}},{"t":"case","label":"City of Covington v. Covington Landing L.P.","cite":"71 F.3d 1221","y":1995,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/71/1221/","by":{"2":"29"}},{"t":"case","label":"Communist Party of U.S. v. Subversive Activities Control Bd.","cite":"367 U.S. 1","y":1961,"id":"1960/12","sc":1,"sum":"The judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"Dawn Donut Co. v. Hart’s Food Stores, Inc.","cite":"267 F.2d 358","y":1959,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/267/358/","by":{"2":"9, 53, 54, 58"}},{"t":"case","label":"Genesis Healthcare Corp. v. Symczyk","cite":"569 U.S. 66","y":2013,"id":"2012/11-1059","sc":1,"sum":"The Court held that a collective action suit on behalf of other \"similarly situated\" employees becomes moot when the individual claim does.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Gorenstein Enters., Inc. v. Quality Care-USA, Inc.","cite":"874 F.2d 431","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/874/431/","ar":2,"sum":"Noting protracted litigation where franchisees “were holding the trademark hostage as a bargaining tactic to pressure [the franchisor] into renegotiating the franchise or settling the suit”.","sumSrc":"brief:2","by":{"2":"59"}},{"t":"case","label":"Hibbs v. Winn","cite":"542 U.S. 88","y":2004,"id":"2003/02-1809","sc":1,"sum":"In a 5-to-4 decision written by Justice Ruth Bader Ginsburg, the Court held that the intention of the Tax Injunction Act (TIA) was to prevent taxpayers from trying to avoid their state taxes through federal litigation. TIA was not intended, however, to prevent all federal interference with state taxation.","sumSrc":"Oyez","by":{"2":"39"}},{"t":"case","label":"Hugo Boss Fashions, Inc. v. Federal Ins. Co.","cite":"252 F.3d 608","y":2001,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/252/608/","by":{"2":"55"}},{"t":"case","label":"K Mart Corp. v. Cartier, Inc.","cite":"485 U.S. 176","y":1988,"id":"1987/86-495","sc":1,"sum":"The judgment is affirmed in part and reversed in part. 252 U. S. App. D. C. 342, 790 F. 2d 903, affirmed in part and reversed in part. JUSTICE KENNEDY delivered the opinion of the Court as to Parts I, II-A, and II-C, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"55"}},{"t":"case","label":"Kotler v. American Tobacco Co.","cite":"981 F.2d 7","y":1992,"url":"https://www.courtlistener.com/c/F.2d/981/7/","by":{"2":"27"}},{"t":"case","label":"Leatherman v. Tarrant Cty. Narcotics Intelligence & Coordination Unit","cite":"507 U.S. 163","y":1993,"id":"1992/91-1657","sc":1,"sum":"L A federal court may not apply a \"heightened pleading standard\"more stringent than the usual pleading requirements of Federal Rule of Civil Procedure 8(a)-in civil rights cases alleging municipal liability under § 1983. First, the heightened standard cannot be justified on the ground that a more relaxed pleading standard would eviscerate municipalities' immunity from suit by subjecting them to expensive and …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"38"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Macmahan Pharmacal Co. v. Denver Chem. Mfg. Co.","cite":"113 F. 468","y":1901,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./113/468/","by":{"2":"9"}},{"t":"case","label":"Matal v. Tam","cite":"137 S. Ct. 1744","y":2017,"id":"2016/15-1293","sc":1,"sum":"The Court determined that the Disparagement Clause prohibits trademarks that disparage the members of a racial or ethnic group and violates the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"Miller v. Glenn Miller Prods.","cite":"454 F.3d 975","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/454/975/","by":{"2":"54"}},{"t":"case","label":"Ohio v. Kovacs","cite":"469 U.S. 274","y":1985,"id":"1984/83-1020","sc":1,"sum":"Petitioner State of Ohio obtained an injunction in state court ordering respondent and other defendants to clean up a hazardous waste disposal site. When the injunction was not complied with, the State obtained the appointment in state court of a receiver, who was directed to take possession of the defendants' property and other assets and to implement the injunction. The receiver took possession of the site but had …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"31, 42"}},{"t":"case","label":"Park ’N Fly, Inc. v. Dollar Park & Fly, Inc.","cite":"469 U.S. 189","y":1985,"id":"1984/83-1132","sc":1,"sum":"The holder of a registered mark may rely on incontestability to enjoin infringement, and an infringement action may not be defended on the grounds that the mark is merely descriptive.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"8"}},{"t":"case","label":"Sharon Steel Corp. v. National Fuel Gas Distrib. Corp.","cite":"872 F.2d 36","y":1989,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/872/36/","by":{"2":"28"}},{"t":"case","label":"Silverstar Enters., Inc. v. Aday","cite":"537 F. Supp. 236","y":1982,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./537/236/","by":{"2":"54"}},{"t":"case","label":"United Drug Co. v. Theodore Rectanus Co.","cite":"248 U.S. 90","y":1918,"id":"scdb/1918-017","sc":1,"sum":"A right of trade-mark is not a right in gross; it exists only as appurtenant to an established business and for the protection of the good will thereof.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"53"}},{"t":"case","label":"Visa, U.S.A., Inc. v. Birmingham Tr. Nat’l Bank","cite":"696 F.2d 1371","y":1982,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/696/1371/","by":{"2":"53"}},{"t":"usc","label":"11 U.S.C. § 502","url":"https://www.law.cornell.edu/uscode/text/11/502","subs":["(c)(2)","(g)(1)"],"by":{"2":"32, 28, 29"}},{"t":"usc","label":"11 U.S.C. § 503","url":"https://www.law.cornell.edu/uscode/text/11/503","subs":["(b)(1)(A)"],"by":{"2":"28, 29"}},{"t":"usc","label":"11 U.S.C. § 506","url":"https://www.law.cornell.edu/uscode/text/11/506","by":{"2":"56"}},{"t":"usc","label":"11 U.S.C. § 507","url":"https://www.law.cornell.edu/uscode/text/11/507","by":{"2":"6"}},{"t":"usc","label":"11 U.S.C. § 542","url":"https://www.law.cornell.edu/uscode/text/11/542","by":{"2":"47"}},{"t":"usc","label":"11 U.S.C. § 552","url":"https://www.law.cornell.edu/uscode/text/11/552","subs":["(b)"],"by":{"2":"50"}},{"t":"usc","label":"11 U.S.C. § 1113","url":"https://www.law.cornell.edu/uscode/text/11/1113","subs":["(a)","(b)","(c)","(d)(2)","(f)"],"by":{"2":"35, 35, 35, 35, 35, 35, 35"}},{"t":"usc","label":"11 U.S.C. § 1141","url":"https://www.law.cornell.edu/uscode/text/11/1141","subs":["(d)(1)"],"by":{"2":"35"}},{"t":"usc","label":"15 U.S.C. § 1058","url":"https://www.law.cornell.edu/uscode/text/15/1058","by":{"2":"9"}},{"t":"usc","label":"15 U.S.C. § 1059","url":"https://www.law.cornell.edu/uscode/text/15/1059","by":{"2":"9"}},{"t":"usc","label":"15 U.S.C. § 1060","url":"https://www.law.cornell.edu/uscode/text/15/1060","subs":["(a)(1)"],"by":{"2":"9, 53"}},{"t":"law","label":"Pub. L. No. 98-353","url":"https://www.govinfo.gov/link/statute/98/333","by":{"2":"6"}},{"t":"case","label":"Chafin v. Chafin","cite":"568 U.S. 165","y":2013,"id":"2012/11-1347","sc":1,"op":5,"sum":"The Court decided that the return of a child to his or her country of residence pursuant to The Hague Convention, does not make an appeal of that order moot.","sumSrc":"Oyez","by":{"3":"21, 23"}},{"t":"case","label":"Coy v. Title Guarantee & Trust Co.","cite":"198 F. 275","y":1912,"court":"D. Or.","url":"https://www.courtlistener.com/c/F./198/275/","by":{"3":"10"}},{"t":"case","label":"De Forest Radio Telephone Co. v. United States","cite":"273 U.S. 236","y":1927,"id":"scdb/1926-148","sc":1,"sum":"A license to make and use a patented article does not depend on formal language, and, as a defense to a subsequent suit for infringement, a license may be inferred from the patent owner's words and acts indicative of his consent, with a reservation of his right to compensation. P. 241. 60 Ct. Cls. 1034, affirmed. DE FOREST CO. v. UNITED STATES.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"20"}},{"t":"case","label":"Florida Department of Revenue v. Piccadilly Cafeterias, Inc.","cite":"554 U.S. 33","y":2008,"id":"2007/07-312","sc":1,"op":1,"sum":"Observing that in enacting Chapter 11, Congress did not have “a single purpose,” but “str[uck] a balance” among multiple competing interests (internal quotation marks omitted).","sumSrc":"opinion","by":{"3":"15"}},{"t":"case","label":"Krebs Chrysler-Plymouth, Inc. v. Valley Motors, Inc.","cite":"141 F.3d 490","y":1998,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/141/490/","by":{"3":"18"}},{"t":"case","label":"Page(s) Marx v. General Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"op":3,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"Reading Co. v. Brown","cite":"391 U.S. 471","y":1968,"id":"1967/127","sc":1,"sum":"Damages resulting from the negligence of a receiver acting within the scope of his authority as receiver give rise to \"actual and necessary\" costs of operating the debtor's business under a Chapter XI arrangement and are thus entitled to the priority status accorded to costs of administration by.§ 64a (1) of the Bankruptcy Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"19"}},{"t":"usc","label":"29 U.S.C. § 158","url":"https://www.law.cornell.edu/uscode/text/29/158","by":{"3":"13"}}]};